code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The full-length color-2 line is the wall; pieces slide toward it.
    if all(v == 2 for v in grid[0]):
        dr, dc, key = 1, 0, lambda cells: min(r for r, c in cells)
    elif all(v == 2 for v in grid[-1]):
        dr, dc, key = -1, 0, lambda cells: -max(r for r, c in cells)
    elif all(row[0] == 2 for row in grid):
        dr, dc, key = 0, 1, lambda cells: min(c for r, c in cells)
    elif all(row[-1] == 2 for row in grid):
        dr, dc, key = 0, -1, lambda cells: -max(c for r, c in cells)
    else:
        raise ValueError("No full color-2 wall")

    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen:
                        seen.add((nr,nc)); stack.append((nr,nc))
            pieces.append((color, cells))

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
    pieces.sort(key=lambda p: key(p[1]))
    for color, cells in pieces:
        cells = list(cells)
        while True:
            moved = [(r+dr, c+dc) for r,c in cells]
            if any(not (0 <= r < h and 0 <= c < w) or out[r][c] != 0 for r,c in moved):
                break
            cells = moved
        for r,c in cells:
            out[r][c] = color
    return out
'''
